const items = $input.all();

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

/* =====================================================
   JOB DATA
===================================================== */

const jobs = items
  .map(item => item.json)
  .filter(job =>
    job['Job Title'] ||
    job['Company'] ||
    job['URL']
  );

const suitableJobs = jobs.filter(job =>
  String(job['AI Decision'] || '').toUpperCase() === 'SUITABLE'
);

const applications = suitableJobs.filter(job =>
  String(job['Application'] || '').trim() !== ''
).length;


/* =====================================================
   JOB CARDS
===================================================== */

const jobCards = suitableJobs.length
  ? suitableJobs.map(job => {

      const title =
        escapeHtml(
          job['Job Title'] || 'Untitled Job'
        );

      const company =
        escapeHtml(
          job['Company'] || 'Unknown Company'
        );

      const location =
        escapeHtml(
          job['Location'] ||
          'Location not specified'
        );

      const jobType =
        escapeHtml(
          job['Job Type'] || 'Not specified'
        );

      const category =
        escapeHtml(
          job['Category'] || 'General'
        );

      const url =
        escapeHtml(
          job['URL'] || '#'
        );

      return `
        <div class="job-card">

          <div class="job-icon">
            💼
          </div>

          <div class="job-main">

            <h3>${title}</h3>

            <div class="company">
              ${company}
            </div>

            <div class="job-meta">

              <span>
                📍 ${location}
              </span>

              <span>
                💼 ${jobType}
              </span>

              <span>
                🏷️ ${category}
              </span>

            </div>

          </div>

          <div class="job-right">

            <span class="suitable-badge">
              ✓ Suitable
            </span>

            <a
              class="view-job"
              href="${url}"
              target="_blank"
              rel="noopener noreferrer"
            >
              View Job
            </a>

          </div>

        </div>
      `;

    }).join('')
  : `
      <div class="empty-state">

        <div class="empty-icon">
          🔍
        </div>

        <h3>No suitable jobs found</h3>

        <p>
          Run a job search to find opportunities
          matching your profile.
        </p>

      </div>
    `;


