async function saveProfile() {

  const status =
    document.getElementById(
      'profileStatus'
    );

  const button =
    document.querySelector(
      '.save-profile'
    );

  const profile = {

    profileId:
      'user-' + Date.now(),

    country:
      document.getElementById(
        'country'
      ).value.trim(),

    experience:
      document.getElementById(
        'experience'
      ).value,

    skills:
      document.getElementById(
        'skills'
      ).value.trim(),

    roles:
      document.getElementById(
        'roles'
      ).value.trim(),

    workPreference: [

      document.getElementById(
        'remote'
      ).checked
        ? 'Remote'
        : null,

      document.getElementById(
        'hybrid'
      ).checked
        ? 'Hybrid'
        : null,

      document.getElementById(
        'onsite'
      ).checked
        ? 'On-site'
        : null

    ]
      .filter(Boolean)
      .join(', ')

  };


  if (
    !profile.country ||
    !profile.skills ||
    !profile.roles
  ) {

    status.textContent =
      '⚠️ Please fill in Country, Skills and Desired Roles.';

    return;
  }


  button.disabled = true;

  button.textContent =
    '⏳ Saving...';

  status.textContent = '';


  try {

    const response =
      await fetch(
        SAVE_PROFILE_URL,
        {
          method: 'POST',

          headers: {
            'Content-Type':
              'application/json'
          },

          body:
            JSON.stringify(profile)
        }
      );


    if (!response.ok) {

      throw new Error(
        'Profile could not be saved.'
      );

    }


    status.textContent =
      '✅ Profile saved successfully!';


    setTimeout(() => {

      window.location.href =
        '?page=dashboard&profileId=' +
        encodeURIComponent(
          profile.profileId
        );

    }, 500);


  } catch (error) {

    console.error(error);

    button.disabled = false;

    button.textContent =
      '🚀 Save & Continue';

    status.textContent =
      '❌ Could not save profile. Please try again.';

  }

}


