      encodeURIComponent(profileId) +
      '&searchId=' +
      encodeURIComponent(searchId);


    await fetch(
      searchUrl,
      {
        method: 'GET',
        mode: 'no-cors'
      }
    );


    button.textContent =
      '🔄 Search running...';


    checkSearchStatus(
      searchId,
      button
    );


  } catch (error) {

    console.error(error);

    button.disabled = false;

    button.textContent =
      '▶ Start Job Search';

    showSearchError(
      'Job search could not be started.'
    );

  }

}


/* =====================================================
   STATUS CHECK
===================================================== */

async function checkSearchStatus(
  searchId,
  button
) {

  try {

    const response =
      await fetch(
        STATUS_URL +
        '?searchId=' +
        encodeURIComponent(searchId)
      );


    const data =
      await response.json();


    const currentStatus =
      String(
        data.Status || ''
      ).toUpperCase();


    const elapsedTime =
      Date.now() -
      searchStartedAt;


    if (
      elapsedTime >
      10 * 60 * 1000
    ) {

      button.disabled = false;

      button.textContent =
        '▶ Start Job Search';

      showSearchError(
        'Search timed out. Please try again.'
      );

      return;

    }


    if (
      currentStatus ===
      'COMPLETED'
    ) {

      button.disabled = false;

      button.textContent =
        '▶ Start Job Search';

      window.location.reload();

      return;

    }


    if (
      currentStatus ===
      'FAILED'
    ) {

      button.disabled = false;

      button.textContent =
        '▶ Start Job Search';

      showSearchError(
        '⚠️ Job Search Failed'
      );

      return;

    }


    if (!currentStatus) {

      button.disabled = false;

      button.textContent =
        '▶ Start Job Search';

      showSearchError(
        'Search status could not be found.'
      );

      return;

    }


    setTimeout(
      function() {

        checkSearchStatus(
          searchId,
          button
        );

      },
      5000
    );


  } catch (error) {

    console.error(
      'Status check failed:',
      error
    );


    setTimeout(
      function() {

        checkSearchStatus(
          searchId,
          button
        );

      },
      5000
    );

  }

}


/* =====================================================
   ERROR MESSAGE
===================================================== */

function showSearchError(message) {

  const error =
    document.getElementById(
      'searchError'
    );

  if (!error) {
    return;
  }

  error.className =
    'search-error';

  error.textContent =
    message;

  error.style.display =
    'block';

}


